/*
# RPG Campaign Chronicles database

Creates plans, profiles, subscriptions, characters, custom attributes, equipment, and per-character journal entries. Adds signup provisioning, updated timestamps, safe plan-limit locking, a 50-attribute limit, simulated plan changes, validation checks, grants, and owner-scoped RLS. Plans are public read-only; all other records are private to the signed-in user. Downgrades retain existing characters but prevent new characters above the new limit.
*/
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS public.plans(id text PRIMARY KEY,name text NOT NULL,character_limit int NOT NULL CHECK(character_limit>0),price_cents int NOT NULL CHECK(price_cents>=0),sort_order int NOT NULL);
CREATE TABLE IF NOT EXISTS public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,email text NOT NULL,display_name text NOT NULL DEFAULT '' CHECK(char_length(display_name)<=50),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,plan_id text NOT NULL REFERENCES public.plans(id),status text NOT NULL CHECK(status IN('active','canceled')),started_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_subscription_per_user ON public.subscriptions(user_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS public.characters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE,name text NOT NULL CHECK(char_length(name) BETWEEN 1 AND 100),species text CHECK(species IS NULL OR char_length(species)<=100),role text CHECK(role IS NULL OR char_length(role)<=100),level int CHECK(level IS NULL OR level BETWEEN 0 AND 10000),health int,max_health int CHECK(max_health IS NULL OR max_health>=0),experience int CHECK(experience IS NULL OR experience>=0),abilities text CHECK(abilities IS NULL OR char_length(abilities)<=5000),biography text CHECK(biography IS NULL OR char_length(biography)<=5000),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.character_attributes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,name text NOT NULL CHECK(char_length(name) BETWEEN 1 AND 50),value text NOT NULL CHECK(char_length(value) BETWEEN 1 AND 100),position int NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS public.equipment(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,item_name text NOT NULL CHECK(char_length(item_name) BETWEEN 1 AND 100),item_type text CHECK(item_type IS NULL OR char_length(item_type)<=50),quantity int NOT NULL DEFAULT 1 CHECK(quantity>=0),description text CHECK(description IS NULL OR char_length(description)<=1000));
CREATE TABLE IF NOT EXISTS public.journal_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,session_date date NOT NULL,title text NOT NULL CHECK(char_length(title) BETWEEN 1 AND 150),campaign_name text CHECK(campaign_name IS NULL OR char_length(campaign_name)<=100),attendees text CHECK(attendees IS NULL OR char_length(attendees)<=500),events text CHECK(events IS NULL OR char_length(events)<=5000),rewards text CHECK(rewards IS NULL OR char_length(rewards)<=2000),notes text CHECK(notes IS NULL OR char_length(notes)<=5000),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.plans VALUES('free','Free',10,0,1),('adventurer','Adventurer',15,500,2),('hero','Hero',25,1000,3),('legend','Legend',50,1500,4) ON CONFLICT(id) DO UPDATE SET name=excluded.name,character_limit=excluded.character_limit,price_cents=excluded.price_cents,sort_order=excluded.sort_order;
CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$BEGIN NEW.updated_at=now();RETURN NEW;END$$;
DROP TRIGGER IF EXISTS characters_updated_at ON public.characters;CREATE TRIGGER characters_updated_at BEFORE UPDATE ON public.characters FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
DROP TRIGGER IF EXISTS journal_updated_at ON public.journal_entries;CREATE TRIGGER journal_updated_at BEFORE UPDATE ON public.journal_entries FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE OR REPLACE FUNCTION public.create_profile_for_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN INSERT INTO public.profiles(id,email,display_name) VALUES(NEW.id,coalesce(NEW.email,''),coalesce(NEW.raw_user_meta_data->>'display_name',''));INSERT INTO public.subscriptions(user_id,plan_id,status) VALUES(NEW.id,'free','active');RETURN NEW;END$$;
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile_for_user();
CREATE OR REPLACE FUNCTION public.enforce_character_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$DECLARE lim int;pn text;cnt int;BEGIN PERFORM 1 FROM public.profiles WHERE id=NEW.user_id FOR UPDATE;SELECT p.character_limit,p.name INTO lim,pn FROM public.subscriptions s JOIN public.plans p ON p.id=s.plan_id WHERE s.user_id=NEW.user_id AND s.status='active';SELECT count(*) INTO cnt FROM public.characters WHERE user_id=NEW.user_id;IF cnt>=coalesce(lim,10) THEN RAISE EXCEPTION 'PLAN_LIMIT_REACHED: Your % plan allows % characters and you have %. Delete a character or upgrade your plan to create another.',coalesce(pn,'Free'),coalesce(lim,10),cnt USING ERRCODE='42501';END IF;RETURN NEW;END$$;
DROP TRIGGER IF EXISTS character_plan_limit ON public.characters;CREATE TRIGGER character_plan_limit BEFORE INSERT ON public.characters FOR EACH ROW EXECUTE FUNCTION public.enforce_character_limit();
CREATE OR REPLACE FUNCTION public.enforce_attribute_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$DECLARE cnt int;BEGIN SELECT count(*) INTO cnt FROM public.character_attributes WHERE character_id=NEW.character_id;IF cnt>=50 THEN RAISE EXCEPTION 'ATTRIBUTE_LIMIT_REACHED: A character can have at most 50 custom attributes.' USING ERRCODE='check_violation';END IF;RETURN NEW;END$$;
DROP TRIGGER IF EXISTS attribute_limit ON public.character_attributes;CREATE TRIGGER attribute_limit BEFORE INSERT ON public.character_attributes FOR EACH ROW EXECUTE FUNCTION public.enforce_attribute_limit();
CREATE OR REPLACE FUNCTION public.change_plan(new_plan_id text) RETURNS public.subscriptions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE old_row public.subscriptions;new_row public.subscriptions;BEGIN IF NOT EXISTS(SELECT 1 FROM public.plans WHERE id=new_plan_id)THEN RAISE EXCEPTION 'UNKNOWN_PLAN';END IF;SELECT * INTO old_row FROM public.subscriptions WHERE user_id=auth.uid() AND status='active' FOR UPDATE;IF old_row.plan_id=new_plan_id THEN RAISE EXCEPTION 'ALREADY_ON_PLAN';END IF;UPDATE public.subscriptions SET status='canceled',ends_at=now() WHERE id=old_row.id;INSERT INTO public.subscriptions(user_id,plan_id,status) VALUES(auth.uid(),new_plan_id,'active') RETURNING * INTO new_row;RETURN new_row;END$$;
ALTER TABLE public.plans ENABLE ROW LEVEL SECURITY;ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.characters ENABLE ROW LEVEL SECURITY;ALTER TABLE public.character_attributes ENABLE ROW LEVEL SECURITY;ALTER TABLE public.equipment ENABLE ROW LEVEL SECURITY;ALTER TABLE public.journal_entries ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.plans TO anon,authenticated;GRANT SELECT ON public.profiles TO authenticated;GRANT UPDATE(display_name) ON public.profiles TO authenticated;GRANT SELECT ON public.subscriptions TO authenticated;GRANT EXECUTE ON FUNCTION public.change_plan(text) TO authenticated;REVOKE EXECUTE ON FUNCTION public.change_plan(text) FROM PUBLIC,anon;GRANT SELECT,INSERT,UPDATE,DELETE ON public.characters,public.character_attributes,public.equipment,public.journal_entries TO authenticated;
DROP POLICY IF EXISTS plans_read ON public.plans;CREATE POLICY plans_read ON public.plans FOR SELECT TO anon,authenticated USING(true);
DROP POLICY IF EXISTS profiles_read ON public.profiles;CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());DROP POLICY IF EXISTS profiles_update ON public.profiles;CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
DROP POLICY IF EXISTS subscriptions_read ON public.subscriptions;CREATE POLICY subscriptions_read ON public.subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid());
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['character_attributes','equipment','journal_entries'] LOOP EXECUTE format('DROP POLICY IF EXISTS %I_read ON public.%I',t,t);EXECUTE format('CREATE POLICY %I_read ON public.%I FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.characters c WHERE c.id=public.%I.character_id AND c.user_id=auth.uid()))',t,t,t);END LOOP;END$$;
DROP POLICY IF EXISTS characters_read ON public.characters;CREATE POLICY characters_read ON public.characters FOR SELECT TO authenticated USING(user_id=auth.uid());DROP POLICY IF EXISTS characters_insert ON public.characters;CREATE POLICY characters_insert ON public.characters FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());DROP POLICY IF EXISTS characters_update ON public.characters;CREATE POLICY characters_update ON public.characters FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());DROP POLICY IF EXISTS characters_delete ON public.characters;CREATE POLICY characters_delete ON public.characters FOR DELETE TO authenticated USING(user_id=auth.uid());
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['character_attributes','equipment','journal_entries'] LOOP EXECUTE format('DROP POLICY IF EXISTS %I_insert ON public.%I',t,t);EXECUTE format('CREATE POLICY %I_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.characters c WHERE c.id=public.%I.character_id AND c.user_id=auth.uid()))',t,t,t);EXECUTE format('DROP POLICY IF EXISTS %I_update ON public.%I',t,t);EXECUTE format('CREATE POLICY %I_update ON public.%I FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.characters c WHERE c.id=public.%I.character_id AND c.user_id=auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.characters c WHERE c.id=public.%I.character_id AND c.user_id=auth.uid()))',t,t,t,t);EXECUTE format('DROP POLICY IF EXISTS %I_delete ON public.%I',t,t);EXECUTE format('CREATE POLICY %I_delete ON public.%I FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.characters c WHERE c.id=public.%I.character_id AND c.user_id=auth.uid()))',t,t,t);END LOOP;END$$;
-- manual fix: supabase grants authenticated users UPDATE on every column of new tables, so the column grant
-- above didn't restrict anything (a user could overwrite their own profiles.email). revoke the table-wide
-- grant first, then allow only display_name. the plan-limit trigger's FOR UPDATE lock still works with it.
REVOKE UPDATE ON public.profiles FROM anon, authenticated;
GRANT UPDATE(display_name) ON public.profiles TO authenticated;
